DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public._award_badges(uuid,uuid)'::regprocedure) INTO f;f:=replace(f,'BEGIN','BEGIN
 INSERT INTO public.badges(user_id,season_id,key,is_demo) SELECT _uid,_sid,''halfway'',p.is_demo FROM public.profiles p WHERE p.id=_uid AND EXISTS(SELECT 1 FROM public.daily_scores d JOIN public.seasons s ON s.id=d.season_id WHERE d.user_id=_uid AND d.season_id=_sid AND d.day>=s.starts_on+19 AND d.completion>=0.6) ON CONFLICT DO NOTHING;');EXECUTE f;
SELECT pg_get_functiondef('public.signature_overview(uuid)'::regprocedure) INTO f;f:=replace(f,'(SELECT max(day) FROM checkins WHERE user_id=p.id AND value>0)','(SELECT max(ci.day) FROM checkins ci JOIN user_habits uh ON uh.id=ci.user_habit_id WHERE ci.user_id=p.id AND uh.season_id=s.id AND ci.value>0)');EXECUTE f; END $$;